krpano.action:
set(n, get(poi_count));

set(ph, %6);
ifnot(ph GT 0, set(ph, 44); );
set(vsc, %7);
ifnot(vsc GT 0, set(vsc, 1.0); );



set(vic, %12);
ifnot(vic, set(vic, 'mac-dinh'); );

set(vw, %13);
ifnot(vw GT 60, set(vw, 0); );
set(vfg, %8);   ifnot(vfg, set(vfg, '#FFFFFF'); );
set(vbg, %9);   ifnot(vbg GE 0, set(vbg, 0x0C0C44); );
set(vbga, %10); ifnot(vbga GE 0, set(vbga, 0.80); );
set(vdot, %11); ifnot(vdot GE 0, set(vdot, 0xC8102E); );


addhotspot(calc('poi_dot_' + n));
set(hotspot[calc('poi_dot_' + n)].type, text);
set(hotspot[calc('poi_dot_' + n)].ath, %1);
set(hotspot[calc('poi_dot_' + n)].atv, %2);
set(hotspot[calc('poi_dot_' + n)].edge, center);
set(hotspot[calc('poi_dot_' + n)].distorted, false);
set(hotspot[calc('poi_dot_' + n)].width, 12);
set(hotspot[calc('poi_dot_' + n)].height, 12);
set(hotspot[calc('poi_dot_' + n)].bg, true);
set(hotspot[calc('poi_dot_' + n)].bgcolor, get(vdot));
set(hotspot[calc('poi_dot_' + n)].bgroundedge, 12);
set(hotspot[calc('poi_dot_' + n)].bgborder, '2 0xFFFFFF 0.95');
set(hotspot[calc('poi_dot_' + n)].bgshadow, '0 1 4 0x000000 0.4');
set(hotspot[calc('poi_dot_' + n)].enabled, false);
set(hotspot[calc('poi_dot_' + n)].zorder, 20);


addhotspot(calc('poi_pole_' + n));
set(hotspot[calc('poi_pole_' + n)].type, text);
set(hotspot[calc('poi_pole_' + n)].ath, %1);
set(hotspot[calc('poi_pole_' + n)].atv, %2);
set(hotspot[calc('poi_pole_' + n)].edge, bottom);
set(hotspot[calc('poi_pole_' + n)].distorted, false);
set(hotspot[calc('poi_pole_' + n)].width, 2);
set(hotspot[calc('poi_pole_' + n)].height, get(ph));
set(hotspot[calc('poi_pole_' + n)].bg, true);
set(hotspot[calc('poi_pole_' + n)].bgcolor, 0xC8102E);
set(hotspot[calc('poi_pole_' + n)].bgalpha, 0.9);
set(hotspot[calc('poi_pole_' + n)].enabled, false);
set(hotspot[calc('poi_pole_' + n)].zorder, 21);


addhotspot(calc('poi_board_' + n));
set(hotspot[calc('poi_board_' + n)].type, text);
set(hotspot[calc('poi_board_' + n)].ath, %1);
set(hotspot[calc('poi_board_' + n)].atv, %2);



set(hotspot[calc('poi_board_' + n)].edge, left);
set(hotspot[calc('poi_board_' + n)].ox, 6);
set(hotspot[calc('poi_board_' + n)].oy, calc(0 - ph - 23));
set(hotspot[calc('poi_board_' + n)].distorted, false);
set(hotspot[calc('poi_board_' + n)].bg, true);
set(hotspot[calc('poi_board_' + n)].bgcolor, get(vbg));
set(hotspot[calc('poi_board_' + n)].bgalpha, get(vbga));

if(vw GT 60, set(hotspot[calc('poi_board_' + n)].width, get(vw)); );
set(hotspot[calc('poi_board_' + n)].bgroundedge, 23);
set(hotspot[calc('poi_board_' + n)].bgborder, '1 0xFFFFFF 0.35');
set(hotspot[calc('poi_board_' + n)].bgshadow, '0 6 22 0x000000 0.5');
set(hotspot[calc('poi_board_' + n)].padding, '9 18 10 18');
set(hotspot[calc('poi_board_' + n)].scale, get(vsc));
set(hotspot[calc('poi_board_' + n)].p_fg, get(vfg));
set(hotspot[calc('poi_board_' + n)].html, '');

txtadd(hotspot[calc('poi_board_' + n)].html, '[b]', %3, '[/b][br]', %4, ' ', %5);
set(hotspot[calc('poi_board_' + n)].zorder, 22);

set(hotspot[calc('poi_board_' + n)].p_title, %3);
set(hotspot[calc('poi_board_' + n)].p_sub,   %4);
set(hotspot[calc('poi_board_' + n)].p_dist,  %5);
set(hotspot[calc('poi_board_' + n)].p_type,  'h');
set(hotspot[calc('poi_board_' + n)].p_pole,  get(ph));
set(hotspot[calc('poi_board_' + n)].p_rot,   0);
set(hotspot[calc('poi_board_' + n)].p_rx,    0);
set(hotspot[calc('poi_board_' + n)].p_ry,    0);
set(hotspot[calc('poi_board_' + n)].p_rz,    0);
set(hotspot[calc('poi_board_' + n)].p_scale, get(vsc));
set(hotspot[calc('poi_board_' + n)].p_bg,  get(vbg));
set(hotspot[calc('poi_board_' + n)].p_bga, get(vbga));
set(hotspot[calc('poi_board_' + n)].p_dot, get(vdot));
set(hotspot[calc('poi_board_' + n)].p_d3d, false);
set(hotspot[calc('poi_board_' + n)].p_icon, get(vic));
set(hotspot[calc('poi_board_' + n)].p_w, get(vw));
poi_build_css(get(n));



set(hotspot[calc('poi_board_' + n)].onmousedown, calc("poi_drag(" + n + ")") );



set(uic, '');
txtadd(uic, 'poi-icons/', get(vic), '.png');
addhotspot(calc('poi_a_' + n));
set(hotspot[calc('poi_a_' + n)].type, image);
