set(hotspot[calc('poi_a_' + n)].ath, %1);
set(hotspot[calc('poi_a_' + n)].atv, %2);
set(hotspot[calc('poi_a_' + n)].edge, right);
set(hotspot[calc('poi_a_' + n)].distorted, false);
set(hotspot[calc('poi_a_' + n)].ox, -6);
set(hotspot[calc('poi_a_' + n)].oy, calc(0 - ph - 23));
set(hotspot[calc('poi_a_' + n)].width, 44);
set(hotspot[calc('poi_a_' + n)].height, 44);
set(hotspot[calc('poi_a_' + n)].scale, get(vsc));
set(hotspot[calc('poi_a_' + n)].enabled, false);
set(hotspot[calc('poi_a_' + n)].zorder, 23);

inc(poi_count);

set(n, get(poi_count));

set(ph, %4);
ifnot(ph GT 0, set(ph, 110); );
set(vsc, %5);
ifnot(vsc GT 0, set(vsc, 1.0); );
set(vfg, %6);  ifnot(vfg, set(vfg, '#FFFFFF'); );
set(vbg, %7);  ifnot(vbg GE 0, set(vbg, 0x0C0C44); );
