set(hotspot[calc('poi_board_' + n)].onmousedown, calc("poi_drag(" + n + ")") );
set(hotspot[calc('poi_board_' + n)].zorder, 22);

inc(poi_count);

set(n, get(poi_count));
set(rg, %4);
ifnot(rg GE -180, set(rg, 0); );

set(vrx, %5);  ifnot(vrx GE -180, set(vrx, 0); );
set(vry, %6);  ifnot(vry GE -180, set(vry, 0); );
set(vrz, %7);  ifnot(vrz GE -180, set(vrz, 0); );

set(vsc, %8);  ifnot(vsc GT 0, set(vsc, 1.0); );
set(vfg, %9);   ifnot(vfg, set(vfg, '#FFFFFF'); );
set(vbg, %10);  ifnot(vbg GE 0, set(vbg, 0x0C0C44); );
set(vbga, %11); ifnot(vbga GE 0, set(vbga, 1); );

set(vdot, %12); ifnot(vdot GE 0, set(vdot, 0xFFFFFF); );

set(vgc, %15);
ifnot(vgc GT 6, set(vgc, 26); );
set(vfg2, get(vdot));

set(vch, '');
txtadd(vch, %16);
if(vch == '', set(vch, 'Đường'); );


set(vd3d, false);

if(vd3d == true,
  ifnot(%5 GE -180, set(vrx, calc(%2 - 90)); );
);


addhotspot(calc('poi_dot_' + n));
set(hotspot[calc('poi_dot_' + n)].type, text);
set(hotspot[calc('poi_dot_' + n)].ath, %1);
set(hotspot[calc('poi_dot_' + n)].atv, %2);
set(hotspot[calc('poi_dot_' + n)].edge, center);
set(hotspot[calc('poi_dot_' + n)].distorted, false);
set(hotspot[calc('poi_dot_' + n)].width, 7);
