set(hotspot[calc('poi_dot_' + n)].visible, true);
set(hotspot[calc('poi_dot_' + n)].zorder, 20);


addhotspot(calc('poi_pole_' + n));
set(hotspot[calc('poi_pole_' + n)].type, text);
set(hotspot[calc('poi_pole_' + n)].ath, %1);
set(hotspot[calc('poi_pole_' + n)].atv, %2);
set(hotspot[calc('poi_pole_' + n)].edge, bottom);
set(hotspot[calc('poi_pole_' + n)].distorted, false);
set(hotspot[calc('poi_pole_' + n)].width, 1);
set(hotspot[calc('poi_pole_' + n)].height, 1);
set(hotspot[calc('poi_pole_' + n)].enabled, false);
set(hotspot[calc('poi_pole_' + n)].visible, false);
set(hotspot[calc('poi_pole_' + n)].zorder, 21);


set(vw, %14);
ifnot(vw GT 40, set(vw, 200); );
addhotspot(calc('poi_a_' + n));
set(hotspot[calc('poi_a_' + n)].type, text);
set(hotspot[calc('poi_a_' + n)].ath, %1);
set(hotspot[calc('poi_a_' + n)].atv, %2);
set(hotspot[calc('poi_a_' + n)].edge, rightbottom);
set(hotspot[calc('poi_a_' + n)].distorted, false);
set(hotspot[calc('poi_a_' + n)].ox, 0);
set(hotspot[calc('poi_a_' + n)].oy, calc(0 - vgc));
set(hotspot[calc('poi_a_' + n)].rotate, get(rg));
set(hotspot[calc('poi_a_' + n)].bg, true);
set(hotspot[calc('poi_a_' + n)].bgcolor, get(vfg2));
set(hotspot[calc('poi_a_' + n)].bgalpha, 1.0);
set(hotspot[calc('poi_a_' + n)].bgroundedge, 0);
set(hotspot[calc('poi_a_' + n)].padding, '8 11 8 11');
set(hotspot[calc('poi_a_' + n)].css, 'color:#FFFFFF; font-family:Inter, Arial, sans-serif; font-size:15px; font-weight:800; letter-spacing:0.6px; text-align:center;');
set(hotspot[calc('poi_a_' + n)].html, get(vch));
set(hotspot[calc('poi_a_' + n)].scale, get(vsc));
set(hotspot[calc('poi_a_' + n)].enabled, false);
set(hotspot[calc('poi_a_' + n)].zorder, 23);


addhotspot(calc('poi_b_' + n));
set(hotspot[calc('poi_b_' + n)].type, text);
set(hotspot[calc('poi_b_' + n)].ath, %1);
set(hotspot[calc('poi_b_' + n)].atv, %2);
set(hotspot[calc('poi_b_' + n)].edge, bottom);
set(hotspot[calc('poi_b_' + n)].distorted, false);
set(hotspot[calc('poi_b_' + n)].ox, 0);
set(hotspot[calc('poi_b_' + n)].oy, 0);
set(hotspot[calc('poi_b_' + n)].width, 2);
set(hotspot[calc('poi_b_' + n)].height, get(vgc));
set(hotspot[calc('poi_b_' + n)].bg, true);
set(hotspot[calc('poi_b_' + n)].bgcolor, get(vfg2));
set(hotspot[calc('poi_b_' + n)].bgalpha, 0.95);
set(hotspot[calc('poi_b_' + n)].enabled, false);
set(hotspot[calc('poi_b_' + n)].zorder, 21);


addhotspot(calc('poi_board_' + n));
