set(hotspot[calc('poi_board_' + n)].ath, %1);
set(hotspot[calc('poi_board_' + n)].atv, %2);

set(hotspot[calc('poi_board_' + n)].edge, leftbottom);
set(hotspot[calc('poi_board_' + n)].ox, 0);
set(hotspot[calc('poi_board_' + n)].oy, calc(0 - vgc));
set(hotspot[calc('poi_board_' + n)].rotate, get(rg));

set(hotspot[calc('poi_board_' + n)].rx, get(vrx));
set(hotspot[calc('poi_board_' + n)].ry, get(vry));
set(hotspot[calc('poi_board_' + n)].rz, get(vrz));
set(hotspot[calc('poi_board_' + n)].distorted, get(vd3d));
set(hotspot[calc('poi_board_' + n)].p_d3d, get(vd3d));


set(hotspot[calc('poi_board_' + n)].bg, true);
set(hotspot[calc('poi_board_' + n)].bgcolor, get(vbg));
set(hotspot[calc('poi_board_' + n)].bgalpha, get(vbga));

set(hotspot[calc('poi_board_' + n)].bgroundedge, 0);
set(hotspot[calc('poi_board_' + n)].padding, '8 14 8 14');
