poi_build_css(get(n));

set(hotspot[calc('poi_board_' + n)].onmousedown, calc("poi_drag(" + n + ")") );
set(hotspot[calc('poi_board_' + n)].zorder, 22);

inc(poi_count);

if(poi_edit_on == true,
  if(poi_sel GE 0,
    set(rbn, calc('poi_board_' + poi_sel));


    if(poi_axis == '2D',
      set(rcur, get(hotspot[get(rbn)].rotate));
      set(nr, calc(rcur + %1));  poi_wrap180();
      set(hotspot[get(rbn)].rotate, get(nr));   set(hotspot[get(rbn)].p_rot, get(nr));

      set(hotspot[calc('poi_a_' + poi_sel)].rotate, get(nr));
    );

    if(poi_axis == 'RX',
      set(nr, calc(hotspot[rbn].rx + %1));      poi_wrap180();
      set(hotspot[get(rbn)].rx, get(nr));       set(hotspot[get(rbn)].p_rx, get(nr));
    );

    if(poi_axis == 'RY',
      set(nr, calc(hotspot[rbn].ry + %1));      poi_wrap180();
      set(hotspot[get(rbn)].ry, get(nr));       set(hotspot[get(rbn)].p_ry, get(nr));
    );

    if(poi_axis == 'RZ',
      set(nr, calc(hotspot[rbn].rz + %1));      poi_wrap180();
      set(hotspot[get(rbn)].rz, get(nr));       set(hotspot[get(rbn)].p_rz, get(nr));
    );

    poi_save_draft();
    set(layer[poi_readout].html, '');
    txtadd(layer[poi_readout].html, 'Nhan duong #', get(poi_sel), '  ·  truc ', get(poi_axis), ' = ', get(nr), ' do   |   2D ', get(hotspot[get(rbn)].p_rot), '  RX ', get(hotspot[get(rbn)].p_rx), '  RY ', get(hotspot[get(rbn)].p_ry), '  RZ ', get(hotspot[get(rbn)].p_rz));
  );
);

if(poi_edit_on == true,
  if(poi_sel GE 0,
    set(sbn, calc('poi_board_' + poi_sel));
    set(ns, calc(hotspot[sbn].scale + %1));
    if(ns LT 0.4, set(ns, 0.4); );
    if(ns GT 4.0, set(ns, 4.0); );
    set(hotspot[get(sbn)].scale, get(ns));
    set(hotspot[get(sbn)].p_scale, get(ns));
    poi_save_draft();
    set(layer[poi_readout].html, '');
    txtadd(layer[poi_readout].html, 'Bang #', get(poi_sel), '  ·  co chu = ', get(ns), 'x   (0.4 .. 4.0)');
  );
);

set(ax_next, '2D');
if(poi_axis == '2D', set(ax_next, 'RX'); );
if(poi_axis == 'RX', set(ax_next, 'RY'); );
if(poi_axis == 'RY', set(ax_next, 'RZ'); );
if(poi_axis == 'RZ', set(ax_next, 'SIZE'); );
if(poi_axis == 'SIZE', set(ax_next, '2D'); );
set(poi_axis, get(ax_next));
poi_axis_label();

set(layer[poi_axis_btn].html, '');
txtadd(layer[poi_axis_btn].html, 'CHE DO: ', get(poi_axis), '  (bam de doi)');


set(lb_r, false);
if(poi_sel GE 0,
  if(hotspot[calc('poi_board_' + poi_sel)].p_type == 'r', set(lb_r, true); );
);

set(layer[poi_up_btn].html, '');
set(layer[poi_dn_btn].html, '');

if(poi_axis == 'SIZE',
  txtadd(layer[poi_up_btn].html, 'CO CHU + (to hon)');
  txtadd(layer[poi_dn_btn].html, 'CO CHU − (nho hon)');
  set(layer[poi_readout].html, 'CO CHU: bam +/- doi buoc 0.1x  (0.4x .. 4.0x) — ap cho MOI loai nhan');
